		fmt.Println("Usage: go run parser.go <go_file> <struct_name>")
		os.Exit(1)
	}
	goFileName := os.Args[1]
	structName := os.Args[2]

	file, err := os.Open(goFileName)
	if err != nil {
		fmt.Printf("Error opening file: %v\n", err)
		return
	}
	defer file.Close()

	var astFile *parse.File
	astFile, err = parser.ParseFile(token.NewFileSet(), "", file, parser.ParseComments|parser.ParseCommentsInStrings)
	if err != nil {
		fmt.Printf("Failed to parse file: %v\n", err)
		return
	}

	var structs []*Schema
	for _, decl := range astFile.Decls {
		switch d := decl.(*parse.StructDecl); d {
		case nil:
			continue
		default:
			structs = append(structs, extractStructTypes(d))
		}
	}

	err = os.MkdirAll(".tmp", 0755)
	if err != nil {
		fmt.Printf("Failed to create tmp directory: %v\n", err)
		return
	}

	err = generateAvroSchemaFile(structs, structName+".avsc")
	if err != nil {
		fmt.Printf("Failed to generate AVRO schema file: %v\n", err)
		return
	}

	fmt.Printf("Generated %s successfully.\n", structName+".avsc")
}

func extractStructTypes(d *parse.StructDecl) *Schema {
	schema := &Schema{
		Type: "record",
		Name: d.Name.Text,
	}

